{
  "concept": "In an Atwood machine, unequal weights create the net force that accelerates the two connected masses, while the same string tension acts on both blocks and their accelerations have equal magnitude in opposite directions.",
  "figureType": "diagram",
  "elements": [
    "beige ceiling beam at the top left",
    "short gray pulley support stem attached to the ceiling",
    "gray pulley wheel with darker outer rim, inner groove, axle, and central hub",
    "yellow cord passing over the pulley groove",
    "left vertical cord segment",
    "right vertical cord segment",
    "left wood-grain square block hanging higher on the left cord, labeled m1",
    "right wood-grain square block hanging lower on the right cord, labeled m2",
    "heading 'Block 1' above the first force diagram",
    "heading 'Block 2' above the second force diagram",
    "isolated wood-grain square block for Block 1",
    "isolated wood-grain square block for Block 2",
    "red upward tension vector on Block 1 labeled T",
    "red upward tension vector on Block 2 labeled T",
    "red downward weight vector on Block 1 labeled w1",
    "red downward weight vector on Block 2 labeled w2",
    "blue acceleration direction arrow beside m1",
    "blue acceleration direction arrow beside m2",
    "ghosted earlier and later positions of the two hanging blocks during motion",
    "small annotation stating 'same string: same tension magnitude'",
    "small annotation stating 'connected blocks: equal-distance motion'"
  ],
  "interactions": [
    {
      "id": "massRatio",
      "type": "slider",
      "label": "Mass ratio m2/m1",
      "range": [
        0.5,
        2,
        0.1
      ],
      "default": 1.5,
      "teaches": "Changing the relative masses changes the two weight vectors and the direction and size of the acceleration, but the tension vectors on the two blocks remain equal because both blocks are attached to the same ideal string"
    },
    {
      "id": "releaseState",
      "type": "button",
      "label": "Release system",
      "states": [
        "held",
        "released",
        "later motion"
      ],
      "default": "held",
      "teaches": "Once released, the heavier block moves downward and the lighter block moves upward by the same distance, showing that the string constraint gives the two masses equal-magnitude accelerations in opposite directions"
    }
  ],
  "demo_steps": [
    {
      "title": "Compare the forces before release",
      "narration": "The two isolated force diagrams show the same upward tension on both blocks, but different downward weights when the masses are unequal. The unequal weights are what make the system accelerate.",
      "state": {
        "massRatio": 1.5,
        "releaseState": "held"
      }
    },
    {
      "title": "Vary the mass difference",
      "narration": "Move the mass-ratio slider: the weight arrows change with mass, and the acceleration arrows grow as the imbalance increases. The two tension arrows remain matched in length because the ideal cord carries one common tension.",
      "state": {
        "massRatio": 2,
        "releaseState": "held"
      }
    },
    {
      "title": "Release the blocks",
      "narration": "After release, the heavier block descends while the lighter block rises. Their position changes are equal in size because one taut string links their motion over the pulley.",
      "state": {
        "massRatio": 1.5,
        "releaseState": "later motion"
      }
    },
    {
      "title": "Balanced special case",
      "narration": "When the masses are equal, the two weight arrows match, the acceleration arrows disappear, and release produces no acceleration of the system.",
      "state": {
        "massRatio": 1,
        "releaseState": "released"
      }
    }
  ],
  "keyInsight": "The blocks do not have separate tensions: one ideal string gives one shared tension, while the difference between the two weights determines the acceleration.",
  "reconstructionNotes": "Use a left pictorial panel and right force-diagram panel, matching the original layout. Draw the pulley assembly in gray under a beige ceiling beam, with a yellow cord over the pulley and two wood-grain blocks hanging at different heights. On the right, show two isolated blocks under the headings 'Block 1' and 'Block 2'. Use red for force vectors and blue for acceleration or motion arrows. Keep the two tension arrows identical in length for every slider setting, while weight arrows scale with m1 and m2. When m2/m1 is greater than 1, m2 has the longer downward weight arrow and accelerates downward while m1 accelerates upward; when the ratio is less than 1, reverse the acceleration directions; when it equals 1, weights match and acceleration arrows vanish. In the release states, show held blocks stationary, then direction arrows at release, then ghosted shifted positions with both blocks displaced by the same amount in opposite vertical directions."
}

