Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Mass ratio m₂/m₁: <output id="massRatioVal">1.5</output><input id="massRatioInput" type="range" min="0.5" max="2" step="0.1" value="1.5" oninput="document.getElementById('massRatioVal').value=this.value;update_massRatio(+this.value)"></label>
<button id="releaseStateInput" onclick="trigger_releaseState()">Release system</button> <span id="releaseStateVal">held</span>
<span id="demoNarration" style="display:inline-block;margin:0;font-size:10px;max-width:180px">The two isolated force diagrams show the same upward tension on both blocks, but different downward weights when the masses are unequal. The unequal weights are what make the system accelerate.</span>
<span><button onclick="prevStep()">◀</button> <span id="stepLabel"></span> <button onclick="nextStep()">▶</button></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 640, H = 450;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

var ratio = 1.5;
var releaseState = 'held';
var releaseStates = ['held', 'released', 'later motion'];
var currentStep = 0;

var red = '#cf3341';
var blue = '#2477c3';
var cord = '#e2b45d';
var cordDark = '#b58a36';

draw.rect(W, H).fill('#ffffff');

var woodPattern = draw.pattern(78, 78, function (add) {
  add.rect(78, 78).fill('#fde3bd');
  add.path('M-8 16 C 12 6, 24 26, 44 15 S 70 9, 88 19').fill('none').stroke({ color: '#f3c99a', width: 6, opacity: 0.65, linecap: 'round' });
  add.path('M-5 34 C 16 25, 29 42, 50 32 S 70 25, 84 37').fill('none').stroke({ color: '#f8d9ae', width: 6, opacity: 0.85, linecap: 'round' });
  add.path('M-8 54 C 14 45, 32 66, 52 52 S 72 48, 88 60').fill('none').stroke({ color: '#f2c58f', width: 5, opacity: 0.55, linecap: 'round' });
});

function haloText(parent, s, x, y, size, opts) {
  opts = opts || {};
  var t = parent.text(s).font({
    family: opts.family || 'sans-serif',
    size: size || 15,
    anchor: opts.anchor || 'start'
  }).fill(opts.fill || '#111').move(x, y);
  if (opts.italic) t.attr({ 'font-style': 'italic' });
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opts.haloWidth || 3, 'stroke-linejoin': 'round' });
  return t;
}

function attachInfo(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, body); });
  return el;
}

function arrow(parent, x1, y1, x2, y2, color, width, head, opacity) {
  var g = parent.group();
  var dx = x2 - x1, dy = y2 - y1;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / len, uy = dy / len;
  var px = -uy, py = ux;
  head = head || 11;
  opacity = opacity == null ? 1 : opacity;
  var lineEndX = x2 - ux * head * 0.75;
  var lineEndY = y2 - uy * head * 0.75;
  g.line(x1, y1, lineEndX, lineEndY).stroke({ color: color, width: width || 4, linecap: 'round' }).opacity(opacity);
  g.polygon([
    [x2, y2],
    [x2 - ux * head + px * head * 0.48, y2 - uy * head + py * head * 0.48],
    [x2 - ux * head - px * head * 0.48, y2 - uy * head - py * head * 0.48]
  ]).fill(color).opacity(opacity);
  return g;
}

function ropeLine(parent, x1, y1, x2, y2) {
  var g = parent.group();
  g.line(x1, y1, x2, y2).stroke({ color: cordDark, width: 6, linecap: 'round' });
  g.line(x1, y1, x2, y2).stroke({ color: cord, width: 4, linecap: 'round' });
  return g;
}

function ropePath(parent, d) {
  var g = parent.group();
  g.path(d).fill('none').stroke({ color: cordDark, width: 7, linecap: 'round', linejoin: 'round' });
  g.path(d).fill('none').stroke({ color: cord, width: 4.5, linecap: 'round', linejoin: 'round' });
  return g;
}

function drawBlock(parent, x, y, w, h, opacity) {
  var g = parent.group().opacity(opacity == null ? 1 : opacity);
  g.rect(w, h).move(x, y).fill(woodPattern).stroke({ color: '#9c9c9c', width: 2 });
  g.line(x + 4, y + h - 7, x + w - 4, y + h - 7).stroke({ color: '#f6cf9f', width: 3, opacity: 0.5 });
  return g;
}

var staticG = draw.group();
staticG.rect(306, 26).move(0, 0).fill('#f6dfb6').stroke({ color: '#8f8f8f', width: 1 });
staticG.rect(156, 8).move(76, 26).fill('#888').stroke({ color: '#585858', width: 1 });
staticG.rect(22, 100).move(143, 26).rx(3).fill('#d7d7d7').stroke({ color: '#909090', width: 2 });
staticG.ellipse(22, 10).center(111, 39).fill('#cfcfcf').stroke({ color: '#666', width: 2 });
staticG.ellipse(22, 10).center(198, 39).fill('#cfcfcf').stroke({ color: '#666', width: 2 });

var ropeStaticG = draw.group();
var pulleyG = draw.group();
pulleyG.circle(126).center(154, 128).fill('#d1d1d1').stroke({ color: '#555', width: 3 });
pulleyG.circle(112).center(154, 128).fill('#bfbfbf').stroke({ color: '#777', width: 2 });
pulleyG.circle(96).center(154, 128).fill('none').stroke({ color: '#eeeeee', width: 5, opacity: 0.8 });
pulleyG.circle(48).center(154, 128).fill('#d7d7d7').stroke({ color: '#777', width: 3 });
pulleyG.circle(25).center(154, 128).fill('#b4b4b4').stroke({ color: '#666', width: 2 });
pulleyG.circle(12).center(154, 128).fill('#eeeeee').stroke({ color: '#777', width: 2 });
ropePath(ropeStaticG, 'M98 128 A56 56 0 0 1 210 128');
attachInfo(pulleyG, 'Pulley redirects the same ideal string tension.', 'Pulley and string', 'In the ideal model, the pulley only changes the direction of the string force. The tension magnitude is the same on both sides of one massless string.');

var pictorialG = draw.group();
var forceG = draw.group();
var noteG = draw.group();

function drawPictorial() {
  pictorialG.clear();

  var sign = ratio > 1.0001 ? 1 : (ratio < 0.9999 ? -1 : 0);
  var baseL = 266, baseR = 364;
  var d = 30;
  var leftY = baseL, rightY = baseR;
  var ghostLY = null, ghostRY = null;

  if (releaseState === 'later motion' && sign !== 0) {
    if (sign > 0) {
      leftY = baseL - d;
      rightY = baseR;
      ghostLY = baseL;
      ghostRY = baseR - d;
    } else {
      leftY = baseL + d;
      rightY = baseR - d;
      ghostLY = baseL;
      ghostRY = baseR;
    }
  }

  if (ghostLY !== null) {
    var gl = drawBlock(pictorialG, 60, ghostLY, 78, 86, 0.23);
    var gr = drawBlock(pictorialG, 171, ghostRY, 78, 86, 0.23);
    gl.rect(78, 86).move(60, ghostLY).fill('none').stroke({ color: blue, width: 1.5, dasharray: '4,4', opacity: 0.55 });
    gr.rect(78, 86).move(171, ghostRY).fill('none').stroke({ color: blue, width: 1.5, dasharray: '4,4', opacity: 0.55 });
  }

  ropeLine(pictorialG, 98, 128, 98, leftY);
  ropeLine(pictorialG, 210, 128, 210, rightY);

  var b1 = drawBlock(pictorialG, 60, leftY, 78, 86, 1);
  var b2 = drawBlock(pictorialG, 171, rightY, 78, 86, 1);

  attachInfo(b1, 'Block 1: mass m₁.', 'Block 1', 'This block is attached to the same string as block 2. Its acceleration magnitude must match block 2 because the string length is fixed.');
  attachInfo(b2, 'Block 2: mass m₂.', 'Block 2', 'Changing m₂ changes its weight. If m₂ is heavier than m₁, it moves downward while m₁ moves upward by the same distance.');

  haloText(pictorialG, 'm₁', 27, leftY + 35, 18, { family: 'serif', italic: true });
  haloText(pictorialG, 'm₂', 256, rightY + 36, 18, { family: 'serif', italic: true });

  if (sign !== 0) {
    var imbalance = Math.min(1, Math.abs(ratio - 1));
    var aLen = 25 + 32 * imbalance;
    var op = releaseState === 'held' ? 0.48 : 0.9;

    if (sign > 0) {
      attachInfo(arrow(pictorialG, 45, leftY + 56, 45, leftY + 56 - aLen, blue, 4, 10, op), 'm₁ accelerates upward.', 'Acceleration constraint', 'When m₂ is heavier, block 2 descends and pulls block 1 upward. The accelerations have equal magnitude because the string is taut.');
      attachInfo(arrow(pictorialG, 267, rightY + 25, 267, rightY + 25 + aLen, blue, 4, 10, op), 'm₂ accelerates downward.', 'Acceleration constraint', 'The heavier side moves downward. The other block moves upward by the same amount at each instant.');
      haloText(pictorialG, 'a', 33, leftY + 54 - aLen, 14, { fill: blue, italic: true, family: 'serif' }).opacity(op);
      haloText(pictorialG, 'a', 276, rightY + 22 + aLen, 14, { fill: blue, italic: true, family: 'serif' }).opacity(op);
    } else {
      attachInfo(arrow(pictorialG, 45, leftY + 25, 45, leftY + 25 + aLen, blue, 4, 10, op), 'm₁ accelerates downward.', 'Acceleration constraint', 'If m₁ is heavier than m₂, the left block descends and the right block rises with the same acceleration magnitude.');
      attachInfo(arrow(pictorialG, 267, rightY + 56, 267, rightY + 56 - aLen, blue, 4, 10, op), 'm₂ accelerates upward.', 'Acceleration constraint', 'The lighter block rises while the heavier block falls. The string constraint ties their displacements together.');
      haloText(pictorialG, 'a', 33, leftY + 24 + aLen, 14, { fill: blue, italic: true, family: 'serif' }).opacity(op);
      haloText(pictorialG, 'a', 276, rightY + 54 - aLen, 14, { fill: blue, italic: true, family: 'serif' }).opacity(op);
    }
  }

  var eqNote = noteG.findOne('#motionNote');
  if (eqNote) eqNote.remove();
  var ng = noteG.group().attr('id', 'motionNote');
  ng.rect(228, 24).move(24, 414).rx(4).fill({ color: '#fff', opacity: 0.78 }).stroke({ color: '#d9d9d9', width: 1 });
  haloText(ng, 'connected blocks: equal-distance motion', 31, 418, 12, { fill: '#444', haloWidth: 2 });
  attachInfo(ng, 'A taut string makes the two displacements equal in size.', 'Equal-distance motion', 'One side of the string cannot lengthen without the other side shortening by the same amount. That is why the acceleration magnitudes are equal and the directions are opposite.');
}

function drawForceDiagrams() {
  forceG.clear();

  haloText(forceG, 'Block 1', 405, 2, 18, { anchor: 'start' });
  haloText(forceG, 'Block 2', 573, 2, 18, { anchor: 'start' });

  var x1 = 436, x2 = 604;
  var top = 183, bh = 86, bw = 77;
  var tRel = 2 * ratio / (1 + ratio);
  var tLen = Math.max(42, Math.min(96, 72 * tRel));
  var w1Len = 68;
  var w2Len = Math.max(32, Math.min(136, 68 * ratio));

  var fb1 = drawBlock(forceG, x1 - bw / 2, top, bw, bh, 1);
  var fb2 = drawBlock(forceG, x2 - bw / 2, top, bw, bh, 1);
  attachInfo(fb1, 'Free-body diagram for m₁.', 'Block 1 force diagram', 'Only two vertical forces act on the hanging block: upward tension and downward weight. The tension shown here has the same magnitude as the tension on block 2.');
  attachInfo(fb2, 'Free-body diagram for m₂.', 'Block 2 force diagram', 'The downward weight changes with m₂, but the upward tension is the same string tension shown for block 1.');

  haloText(forceG, 'm₁', x1 - 73, top + 34, 18, { family: 'serif', italic: true });
  haloText(forceG, 'm₂', x2 - 73, top + 34, 18, { family: 'serif', italic: true });

  var t1 = arrow(forceG, x1, top, x1, top - tLen, red, 4, 13, 1);
  var t2 = arrow(forceG, x2, top, x2, top - tLen, red, 4, 13, 1);
  attachInfo(t1, 'Tension T on block 1.', 'Same tension', 'This is not a separate tension chosen for block 1. In an ideal single cord, the tension magnitude is common throughout the cord.');
  attachInfo(t2, 'Tension T on block 2.', 'Same tension', 'This arrow is always the same length as the tension arrow on block 1. A single ideal string gives one shared tension.');

  haloText(forceG, 'T⃗', x1 - 29, top - tLen + 14, 17, { family: 'serif' });
  haloText(forceG, 'T⃗', x2 - 29, top - tLen + 14, 17, { family: 'serif' });

  var w1 = arrow(forceG, x1, top + bh, x1, top + bh + w1Len, red, 4, 13, 1);
  var w2 = arrow(forceG, x2, top + bh, x2, top + bh + w2Len, red, 4, 13, 1);
  attachInfo(w1, 'Weight w₁ = m₁g.', 'Weight of block 1', 'The weight arrow scales with mass. Here m₁ is the reference mass, so w₁ stays fixed while the slider changes m₂.');
  attachInfo(w2, 'Weight w₂ = m₂g.', 'Weight of block 2', 'Changing the mass ratio changes this arrow. The difference between w₂ and w₁ creates the net force that accelerates the system.');

  haloText(forceG, 'w⃗₁', x1 - 34, top + bh + w1Len - 47, 17, { family: 'serif' });
  haloText(forceG, 'w⃗₂', x2 - 34, top + bh + w2Len - 47, 17, { family: 'serif' });

  var sign = ratio > 1.0001 ? 1 : (ratio < 0.9999 ? -1 : 0);
  if (sign !== 0) {
    var smallLen = 14 + 20 * Math.min(1, Math.abs(ratio - 1));
    var a1x = x1 + 54, a2x = x2 + 28;
    if (sign > 0) {
      arrow(forceG, a1x, top + 56, a1x, top + 56 - smallLen, blue, 3, 8, 0.75);
      arrow(forceG, a2x, top + 30, a2x, top + 30 + smallLen, blue, 3, 8, 0.75);
    } else {
      arrow(forceG, a1x, top + 30, a1x, top + 30 + smallLen, blue, 3, 8, 0.75);
      arrow(forceG, a2x, top + 56, a2x, top + 56 - smallLen, blue, 3, 8, 0.75);
    }
  }

  var sameNote = forceG.group();
  sameNote.rect(220, 23).move(366, 47).rx(4).fill({ color: '#fff', opacity: 0.82 }).stroke({ color: '#dddddd', width: 1 });
  haloText(sameNote, 'same string: same tension magnitude', 373, 51, 12, { fill: '#444', haloWidth: 2 });
  sameNote.line(436, 70, 436, Math.max(84, top - tLen + 5)).stroke({ color: '#888', width: 1, dasharray: '3,3' });
  sameNote.line(548, 70, 604, Math.max(84, top - tLen + 5)).stroke({ color: '#888', width: 1, dasharray: '3,3' });
  attachInfo(sameNote, 'Both tension arrows are the same length.', 'One string, one tension', 'The force diagrams should not be read as having two independent tensions. In this ideal Atwood machine, the cord transmits the same tension magnitude to both blocks.');
}

function renderAll() {
  drawPictorial();
  drawForceDiagrams();
  var rLabel = document.getElementById('releaseStateVal');
  if (rLabel) rLabel.textContent = releaseState;
}

function update_massRatio(v) {
  ratio = +v;
  renderAll();
}

function setReleaseState(s) {
  releaseState = s;
  renderAll();
}

function trigger_releaseState() {
  var i = releaseStates.indexOf(releaseState);
  releaseState = releaseStates[(i + 1) % releaseStates.length];
